WITH ec AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, DATE_TRUNC('month',BULAN)::DATE mo, SUM(IFF(GROUP_LEVEL IN ('BIAYA PERAWATAN'),RP_ACTUAL,0))/1000 a_up,SUM(IFF(GROUP_LEVEL IN ('BIAYA INFRA'),RP_ACTUAL,0))/1000 a_inf,SUM(IFF(GROUP_LEVEL IN ('BIAYA PEMUPUKAN'),RP_ACTUAL,0))/1000 a_fert,SUM(IFF(GROUP_LEVEL IN ('BIAYA PANEN'),RP_ACTUAL,0))/1000 a_harv,SUM(IFF(GROUP_LEVEL IN ('TRANSPORT PANEN'),RP_ACTUAL,0))/1000 a_trans,SUM(IFF(GROUP_LEVEL IN ('BIAYA UMUM','COST SEWA AMP'),RP_ACTUAL,0))/1000 a_ovh,SUM(IFF(GROUP_LEVEL IN ('BIAYA PENYUSUTAN'),RP_ACTUAL,0))/1000 a_depr, SUM(IFF(GROUP_LEVEL IN ('BIAYA PERAWATAN'),RP_BUDGET,0))/1000 b_up,SUM(IFF(GROUP_LEVEL IN ('BIAYA INFRA'),RP_BUDGET,0))/1000 b_inf,SUM(IFF(GROUP_LEVEL IN ('BIAYA PEMUPUKAN'),RP_BUDGET,0))/1000 b_fert,SUM(IFF(GROUP_LEVEL IN ('BIAYA PANEN'),RP_BUDGET,0))/1000 b_harv,SUM(IFF(GROUP_LEVEL IN ('TRANSPORT PANEN'),RP_BUDGET,0))/1000 b_trans,SUM(IFF(GROUP_LEVEL IN ('BIAYA UMUM','COST SEWA AMP'),RP_BUDGET,0))/1000 b_ovh,SUM(IFF(GROUP_LEVEL IN ('BIAYA PENYUSUTAN'),RP_BUDGET,0))/1000 b_depr, MAX(TON_ACTUAL) ton, MAX(TON_BUDGET) tonb, MAX(HA_ACTUAL) ha, MAX(HA_BUDGET) hab FROM PRD_DB_PRESENTATION.PRS_COST.ESTATE_COST WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2,3), pr AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, DATE_TRUNC('month',TANGGAL_PANEN)::DATE mo, SUM(HA_PANEN) hap, SUM(HK) hk FROM PRD_DB_INTEGRATION.INT_PANEN.INT_PENCAPAIAN_PRODUKSI_PANEN WHERE KODE_BA IN ('2121','2124','2131','2122') AND TANGGAL_PANEN>='2026-01-01' AND TANGGAL_PANEN<'2026-10-01' GROUP BY 1,2,3), bb AS (SELECT ba, afd, mo, v - COALESCE(LAG(v) OVER (PARTITION BY ba, afd ORDER BY mo), 0) bbc FROM (SELECT ba, afd, m0 mo, SUM(y) v FROM (SELECT DECODE(s.KODE_BA,'2122','2131',s.KODE_BA) ba, s.KODE_AFD afd, mths.m0, s.YTD_TON_BBC y FROM PRD_DB_INTEGRATION.INT_PANEN.INT_PENCAPAIAN_PRODUKSI_PANEN s JOIN (SELECT DATEADD(month,seq4(),'2026-01-01'::DATE) m0 FROM TABLE(GENERATOR(ROWCOUNT=>9))) mths ON s.TANGGAL_PANEN<=LAST_DAY(mths.m0) WHERE s.KODE_BA IN ('2121','2124','2131','2122') AND s.TANGGAL_PANEN>='2026-01-01' QUALIFY ROW_NUMBER() OVER (PARTITION BY s.KODE_BA,s.KODE_AFD,s.KODE_BLOK,mths.m0 ORDER BY s.TANGGAL_PANEN DESC)=1) GROUP BY 1,2,3)), hb AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, DATE_TRUNC('month',BULAN)::DATE mo, SUM(HK_BUDGET) hkb FROM PRD_DB_INTEGRATION.INT_KARYAWAN.INT_HK_BUDGET WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2,3), keys AS (SELECT ba,afd,mo FROM ec UNION SELECT ba,afd,mo FROM pr UNION SELECT ba,afd,mo FROM hb UNION SELECT ba,afd,mo FROM bb), f AS (SELECT k.ba,k.afd,k.mo, COALESCE(ec.ton,0) ton, COALESCE(bb.bbc,0) bbc, COALESCE(pr.hap,0) hap, COALESCE(pr.hk,0) hk, COALESCE(ec.tonb,0) tonb, COALESCE(hb.hkb,0) hkb, COALESCE(ec.ha,0) ha, COALESCE(ec.hab,0) hab, COALESCE(ec.a_up,0) a_up,COALESCE(ec.a_inf,0) a_inf,COALESCE(ec.a_fert,0) a_fert,COALESCE(ec.a_harv,0) a_harv,COALESCE(ec.a_trans,0) a_trans,COALESCE(ec.a_ovh,0) a_ovh,COALESCE(ec.a_depr,0) a_depr, COALESCE(ec.b_up,0) b_up,COALESCE(ec.b_inf,0) b_inf,COALESCE(ec.b_fert,0) b_fert,COALESCE(ec.b_harv,0) b_harv,COALESCE(ec.b_trans,0) b_trans,COALESCE(ec.b_ovh,0) b_ovh,COALESCE(ec.b_depr,0) b_depr FROM keys k LEFT JOIN ec ON ec.ba=k.ba AND ec.afd=k.afd AND ec.mo=k.mo LEFT JOIN pr ON pr.ba=k.ba AND pr.afd=k.afd AND pr.mo=k.mo LEFT JOIN bb ON bb.ba=k.ba AND bb.afd=k.afd AND bb.mo=k.mo LEFT JOIN hb ON hb.ba=k.ba AND hb.afd=k.afd AND hb.mo=k.mo WHERE k.afd IS NOT NULL), pd AS (SELECT 'Y' p, DATE '2026-01-01' s, DATE '2026-09-01' e, 9 n UNION ALL SELECT 'M', DATE '2026-09-01', DATE '2026-09-01', 1 UNION ALL SELECT 'A', DATE '2026-01-01', DATE '2026-08-01', 8) SELECT ba,afd,pd.p, ROUND(SUM(bbc),1) FROM f JOIN pd ON f.mo BETWEEN pd.s AND pd.e GROUP BY 1,2,3 ORDER BY 1,2,3